// Claudeのレスポンス(content[0].text にJSON文字列)をパースしてPOST用bodyを作る
const raw = $input.first().json.content?.[0]?.text ?? '{}';
let parsed;
try {
  const match = raw.match(/\{[\s\S]*\}/);
  parsed = JSON.parse(match ? match[0] : raw);
} catch (e) {
  throw new Error('Claude応答のJSONパースに失敗しました: ' + raw.slice(0, 200));
}
return [{
  json: {
    title: parsed.title,
    meta_description: parsed.meta_description,
    body_md: parsed.body_md,
    tags: parsed.tags ?? [],
    status: 'draft'
  }
}];
